<script setup lang="ts">
import { onMounted, ref } from 'vue'
import axios from 'axios'
import api from '../plugins/axios'

const pedidos = ref<any[]>([]); const cargando = ref(true); const error = ref(''); const mensaje = ref('')
const estado = ref(''); const fechaEntrega = ref('')
const cargar = async () => { cargando.value = true; try { const { data } = await api.get('/pedidos', { params: { estado: estado.value || undefined, fechaEntrega: fechaEntrega.value || undefined } }); pedidos.value = data } catch (e) { error.value = axios.isAxiosError(e) ? e.response?.data?.message ?? 'No se pudieron cargar los pedidos.' : 'No se pudieron cargar los pedidos.' } finally { cargando.value = false } }
async function actualizar(id: number, accion: 'listo' | 'entregado') { try { await api.patch(`/pedidos/${id}/${accion}`); mensaje.value = `Pedido #${id} actualizado.`; await cargar() } catch (e) { error.value = axios.isAxiosError(e) ? e.response?.data?.message ?? 'No se pudo actualizar.' : 'No se pudo actualizar.' } }
onMounted(cargar)
</script>
<template><section class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="text-uppercase fw-semibold miskila-accent mb-1">Operación</p><h1 class="h2 fw-bold mb-0">Panel de pedidos</h1></div><RouterLink class="btn btn-outline-primary" to="/panel/personalizado">Nuevo personalizado</RouterLink></div><div class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="row g-2"><div class="col-md-5"><label class="form-label">Fecha de entrega</label><input v-model="fechaEntrega" class="form-control" type="date" /></div><div class="col-md-5"><label class="form-label">Estado</label><select v-model="estado" class="form-select"><option value="">Todos</option><option value="pendiente_pago">Pendiente de pago</option><option value="pagado">Pagado</option><option value="no_pagado">No pagado</option><option value="entregado">Entregado</option></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100" type="button" @click="cargar">Filtrar</button></div></div></div></div><div v-if="mensaje" class="alert alert-success">{{ mensaje }}</div><div v-if="error" class="alert alert-danger">{{ error }}</div><div v-if="cargando" class="text-center text-secondary">Cargando…</div><div v-else class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Cliente</th><th>Entrega</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="pedido in pedidos" :key="pedido.idPedido"><td>#{{ pedido.idPedido }}</td><td>{{ pedido.cliente?.nombreCompleto || pedido.cliente?.celular }}</td><td>{{ pedido.capacidadDia?.fecha }} {{ pedido.horaEntrega }}</td><td>{{ Number(pedido.total).toFixed(2) }} Bs</td><td>{{ pedido.estado }}</td><td class="text-nowrap"><button v-if="!pedido.listo" class="btn btn-sm btn-outline-primary me-1" type="button" @click="actualizar(pedido.idPedido, 'listo')">Listo</button><button v-if="pedido.estado === 'pagado'" class="btn btn-sm btn-outline-success" type="button" @click="actualizar(pedido.idPedido, 'entregado')">Entregado</button><RouterLink class="btn btn-sm btn-link" :to="{ name: 'verificacion-pago', params: { id: pedido.idPedido } }">Pago</RouterLink></td></tr></tbody></table></div></section></template>
